// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, type(uint256).max / 2);
        address actor = address(new Reverter());
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        bool ok;
        vm.prank(actor);
        try c.withdrawBalance() { ok = true; } catch { ok = false; }
        // A payout the counterparty refuses must make withdrawBalance revert.
        assertTrue(!ok && c.getBalance(actor) == amount);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
